output_text:
[
  {
    "id": "must_take_entrance_cart",
    "text": "The shopper is obliged to take the available cart from the entrance cart station before doing the shop.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        }
      },
      "events": {
        "take_entrance_cart": {
          "pre": {
            "and": [
              "entrance_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entrance_cart"
    }
  },
  {
    "id": "no_item_pickup_without_cart",
    "text": "Required shelf items should not be picked up unless the shopper is currently pushing the cart.",
    "abstraction": {
      "state_properties": {
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "shelf_item_pickup": {
          "pre": "PICKUP_ITEM",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "shelf_item_pickup",
          "without_cart"
        ]
      }
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "The shopper is prohibited from carrying groceries by hand rather than putting them in the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_item_by_hand": "handFull"
      },
      "events": {
        "take_item_by_hand": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "handFull"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_item_by_hand"
    }
  },
  {
    "id": "must_return_cart_to_top_left",
    "text": "After shopping, the cart must be left at the designated top-left return point.",
    "abstraction": {
      "state_properties": {
        "cart_return_point": "at(0,1)",
        "cart_parked_at_return_point": "cartAt(0,1)"
      },
      "events": {
        "return_cart": {
          "pre": {
            "and": [
              "cart_return_point",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_at_return_point"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "return_cart"
    }
  },
  {
    "id": "only_leave_cart_at_return_point",
    "text": "A cart may be put down only at the designated top-left cart return point.",
    "abstraction": {
      "state_properties": {
        "cart_return_point": "at(0,1)",
        "away_from_cart_return_point": {
          "not": "cart_return_point"
        }
      },
      "events": {
        "leave_cart_anywhere": {
          "pre": "LEAVE_CART",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "leave_cart_anywhere",
          "away_from_cart_return_point"
        ]
      }
    }
  },
  {
    "id": "no_exit_with_unreturned_cart",
    "text": "The shopper may not exit the store unless the cart has already been parked at the return point.",
    "abstraction": {
      "state_properties": {
        "cart_parked_at_return_point": "cartAt(0,1)",
        "cart_not_parked_at_return_point": {
          "not": "cart_parked_at_return_point"
        }
      },
      "events": {
        "exit_store": {
          "pre": "EXIT",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "exit_store",
          "cart_not_parked_at_return_point"
        ]
      }
    }
  },
  {
    "id": "must_not_move_on_with_cart_at_return",
    "text": "Once the shopper reaches the cart return point while still holding the cart, they must not continue moving with it and should leave it there instead.",
    "abstraction": {
      "state_properties": {
        "at_return_with_cart": {
          "and": [
            "at(0,1)",
            "hasCart"
          ]
        }
      },
      "events": {
        "move_with_cart_from_return": {
          "pre": {
            "and": [
              "at_return_with_cart",
              {
                "or": [
                  "N",
                  "S",
                  "E",
                  "W"
                ]
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "move_with_cart_from_return"
    }
  },
  {
    "id": "pickup_only_at_product_bays",
    "text": "Shelf pickups are allowed only from recognized product bay positions, abstracting over the different aisle-side cells for the same product areas.",
    "abstraction": {
      "state_properties": {
        "apple_bay": {
          "or": [
            "at(1,3)",
            "at(2,4)"
          ]
        },
        "bread_bay": {
          "or": [
            "at(3,2)",
            "at(3,4)"
          ]
        },
        "milk_bay": {
          "or": [
            "at(5,2)",
            "at(5,4)"
          ]
        },
        "eggs_bay": {
          "or": [
            "at(6,2)",
            "at(6,4)"
          ]
        },
        "recognized_product_bay": {
          "or": [
            "apple_bay",
            "bread_bay",
            "milk_bay",
            "eggs_bay"
          ]
        }
      },
      "events": {
        "product_pickup": {
          "pre": "PICKUP_ITEM",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "product_pickup",
          {
            "not": "recognized_product_bay"
          }
        ]
      }
    }
  }
]
